/* DOTP dashboard: shared navigation, real league data, and linked exploration. */
(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n || 0).toLocaleString('en-US', {maximumFractionDigits:1});
const date = value => value ? new Date(String(value).slice(0,10)+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : 'Date unavailable';
const initials = name => (name || '?').split(/\s+/).map(x=>x[0]).slice(0,2).join('');
const normal = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const iconPaths = {
 overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 teams:'<path d="M12 3l8 4v6c0 5-8 8-8 8s-8-3-8-8V7z"/><path d="M8 12l3 3 5-6"/>',
 players:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0112 0v3M16 5a3 3 0 010 6M18 15a5 5 0 013 4v2"/>',
 trades:'<path d="M4 7h16m-4-4l4 4-4 4M20 17H4m4-4l-4 4 4 4"/>',
 standings:'<path d="M5 20v-7h4v7M10 20V4h4v16M15 20V9h4v11M3 20h18"/>',
 drafts:'<path d="M8 4H5v17h14V4h-3M9 3h6v4H9zM8 12h8M8 16h5"/>',
 history:'<path d="M3 11a9 9 0 119 10M3 4v7h7M12 7v6l4 2"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="M16 16l5 5"/>',
 arrow:'<path d="M4 12h16m-5-5l5 5-5 5"/>',
 chevron:'<path d="M9 5l7 7-7 7"/>',
 close:'<path d="M6 6l12 12M18 6L6 18"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 trophy:'<path d="M7 3h10v6a5 5 0 01-10 0zM7 5H3v3a4 4 0 004 4M17 5h4v3a4 4 0 01-4 4M12 14v6M8 21h8"/>',
 ball:'<circle cx="12" cy="12" r="9"/><path d="M5 5c8 4 8 10 0 14M19 5c-8 4-8 10 0 14"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',
 compare:'<path d="M8 4v16M16 4v16M4 8h8M12 16h8M5 5L2 8l3 3M19 13l3 3-3 3"/>',
 check:'<path d="M4 12l5 5L20 6"/>',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name] || iconPaths.ball}</svg>`;
let D={}, owners=[], ownerMap={}, playerMap={}, rosterMap={}, stintsByPlayer={}, view=document.body.dataset.page;
let year, currentYear, selectedOwner, page=1, sortKey='player_name', sortDirection=1, tableRows=[], pageSize=20, dialogTrigger;
const params=()=>new URLSearchParams(location.search);
const param=(key,fallback='')=>params().get(key) ?? fallback;
function setParams(values, push=false) {const p=params(); for(const [k,v] of Object.entries(values)) v === '' || v == null ? p.delete(k) : p.set(k,v); const url=location.pathname+(p.size?'?'+p:''); history[push?'pushState':'replaceState']({},'',url);}
function url(file, values={}) {const p=new URLSearchParams({season:String(year),...values});return `${file}?${p}`;}
const teamUrl=(name)=>url('team.html',{owner:name});
const playerUrl=(id)=>url('player.html',{id});
const teamName=(name,season=year)=>ownerMap[name]?.history.find(h=>h.season===Number(season))?.team_name || ownerMap[name]?.current_team || name;
const colors=[['#e7ecdf','#58633e'],['#eee6d7','#84693f'],['#f0e1dc','#945a48'],['#dde8e5','#3b6b61'],['#e9e5d9','#716342'],['#e0e7ee','#526c87'],['#e5e8da','#6b7441'],['#e9e4ed','#756580'],['#e2eadb','#557243'],['#e7e0d6','#7b6350'],['#dce8e1','#3f6f56'],['#eee6d6','#947943']];
function badge(name,large=false) {const owner=ownerMap[name], c=colors[owner?.color_index || 0];const word=owner?.current_team || name;const letters=word.replace(/^(The |Gimmie )/,'').replace(/[’']/g,'').split(/[\s&]+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();return `<span class="team-badge${large?' large':''}" style="--badge-bg:${c[0]};--badge-ink:${c[1]}" aria-hidden="true">${esc(letters)}</span>`;}
function teamCell(name,season=year) {return `<a class="team-cell" href="${teamUrl(name)}">${badge(name)}<span><strong>${esc(teamName(name,season))}</strong><small>${esc(name)}</small></span></a>`;}
const playerLink=(id,name,avatar=true)=>`<a href="${playerUrl(id)}" class="player-button" title="Open ${esc(name)}’s player journey">${avatar?`<span class="player-avatar" aria-hidden="true">${esc(initials(name))}</span>`:''}<span>${esc(name)}</span></a>`;
const ownerOptions=(selected,all=false)=>`${all?'<option value="">All teams</option>':''}${owners.map(o=>`<option value="${esc(o.real_name)}" ${o.real_name===selected?'selected':''}>${esc(o.current_team)}</option>`).join('')}`;
const seasonRows=(season=year)=>D.standings.season_standings.filter(r=>r.season===Number(season)).sort((a,b)=>a.rank-b.rank);
const ownerStanding=(owner,season=year)=>D.standings.season_standings.find(r=>r.owner_real_name===owner&&r.season===Number(season));
const empty=(title,detail='Try a different search or clear your filters.')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;
const panel=(title,subtitle,body,action='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;
const link=(label,href)=>`<a class="text-link" href="${href}">${label}${icon('arrow')}</a>`;
const metric=(label,value,note,ic='standings')=>`<div class="metric">${icon(ic)}<label>${label}</label><div class="value num">${value}</div><div class="metric-note">${note}</div></div>`;
function change(owner){const a=ownerStanding(owner),b=ownerStanding(owner,year-1);if(!a||!b)return '<span class="change">—</span>';const delta=b.rank-a.rank;return `<span class="change ${delta>0?'up':delta<0?'down':''}" title="Rank change from ${year-1}">${delta>0?'↑':delta<0?'↓':'–'} ${delta?Math.abs(delta):'Even'}</span>`;}
function shell() {
 const nav=[['overview','Overview','index.html'],['teams','Teams','team.html'],['players','Players','player_history.html'],['trades','Trades','trade.html'],['standings','Standings','standings.html'],['drafts','Draft room','drafts.html'],['history','League history','history.html']];
 const title=nav.find(n=>n[0]===view)?.[1] || 'Player profile';
 $('#app').innerHTML=`<button class="backdrop-menu" aria-label="Close navigation" data-menu></button><aside class="sidebar"><a class="brand" href="${url('index.html')}"><img src="assets/dotp-crest.png" alt="Ducks on the Pond crest"><span><strong>DOTP</strong><small>DYNASTY BASEBALL</small></span></a><div class="nav-label">THE CLUBHOUSE</div><nav aria-label="Main navigation">${nav.map(([key,label,file])=>`<a class="side-link ${view===key || (view==='player'&&key==='players')?'active':''}" ${view===key?'aria-current="page"':''} href="${url(file)}">${icon(key)}${label}${view===key?`<span class="chevron">${icon('chevron')}</span>`:''}</a>`).join('')}</nav><div class="side-footer"><div class="league-note"><strong>Eight seasons. One league.</strong>Every roster move has a story.<br>Est. 2019 · 12 teams</div><div class="team-picker"><button type="button" id="selected-team-button" class="sidebar-person" aria-expanded="false" aria-controls="selected-team-options" aria-label="Choose your team">${badge(selectedOwner)}<span><strong>${esc(ownerMap[selectedOwner]?.current_team)}</strong><small>Your team · Change ${icon('chevron').replace('class="icon"','class="icon" style="display:inline;width:10px;height:10px"')}</small></span></button><section id="selected-team-options" class="team-picker-options" aria-label="Choose your team" hidden><div class="team-picker-title">YOUR SELECTED TEAM</div>${owners.map(o=>`<button type="button" class="team-picker-option" data-select-owner="${esc(o.real_name)}" aria-pressed="${o.real_name===selectedOwner}">${badge(o.real_name)}<span><strong>${esc(o.current_team)}</strong><small>${esc(o.real_name)}</small></span>${o.real_name===selectedOwner?icon('check'):''}</button>`).join('')}</section></div></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false" data-menu>${icon('menu')}</button><div class="breadcrumb">The clubhouse <span aria-hidden="true"> / </span> <b>${title}</b></div><div class="top-search"><div class="search-field">${icon('search')}<input id="global-search" type="search" aria-label="Search players and teams" placeholder="Search players, teams…" autocomplete="off" aria-controls="global-results" aria-expanded="false"><span class="key-hint">/</span></div><div id="global-results" class="search-results" hidden></div></div><span class="updated"><span class="fresh-dot"></span>Updated ${date(D.refresh_status.refreshed_at)}</span><label class="season-control"><span>Season</span><select id="season-select" aria-label="Season">${D.teams.meta.seasons.slice().reverse().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></header><main id="main-content" class="page" tabindex="-1"></main></div>`;
 $('#selected-team-button').addEventListener('click',toggleTeamPicker);
 $('#season-select').addEventListener('change',e=>{setParams({season:e.target.value,page:null});year=Number(e.target.value);page=1;render();shellNavUpdate();});
 $('#global-search').addEventListener('input',globalSearch);
 $('#global-search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#global-results a')?.focus();}if(e.key==='Escape')closeSearch();if(e.key==='Enter'){$('#global-results a')?.click();}});
}
function closeTeamPicker(restoreFocus=false) {
 const options=$('#selected-team-options');
 if(!options || options.hidden)return;
 options.hidden=true;
 $('#selected-team-button').setAttribute('aria-expanded','false');
 if(restoreFocus)$('#selected-team-button').focus();
}
function toggleTeamPicker() {
 const options=$('#selected-team-options');
 const opening=options.hidden;
 options.hidden=!opening;
 $('#selected-team-button').setAttribute('aria-expanded',String(opening));
 if(opening)options.querySelector('[aria-pressed="true"]')?.focus();
}
function selectTeam(owner) {
 if(!ownerMap[owner])return;
 selectedOwner=owner;
 try{localStorage.setItem('dotp_selected_owner',owner);}catch{}
 // A preference change updates this clubhouse, but ordinary team browsing does not change the preference.
 if(view==='teams'){
  page=1;
  setParams({owner,q:null,filterOwner:null,status:null,position:null,page:null,compare:null});
 }
 document.body.classList.remove('menu-open');
 shell();render();
 $('#selected-team-button').focus();
 if(matchMedia('(max-width:700px)').matches)$('#main-content').focus();
}
function shellNavUpdate(){document.querySelectorAll('.side-link,.brand').forEach(a=>{const u=new URL(a.href);u.searchParams.set('season',year);a.href=u.pathname+u.search;});}
function globalSearch(e){const q=normal(e.target.value).trim(), box=$('#global-results');if(q.length<2){closeSearch();return;}const ts=owners.filter(o=>normal(o.current_team+' '+o.real_name+' '+o.history.map(h=>h.team_name).join(' ')).includes(q)).slice(0,4);const ps=Object.entries(playerMap).filter(([,p])=>normal(p.player_name).includes(q)).slice(0,7);box.innerHTML=`${ts.length?'<div class="search-group">TEAMS</div>'+ts.map(o=>`<a class="search-result" href="${teamUrl(o.real_name)}">${badge(o.real_name)}<span><strong>${esc(o.current_team)}</strong><small>${esc(o.real_name)}</small></span></a>`).join(''):''}${ps.length?'<div class="search-group">PLAYERS</div>'+ps.map(([id,p])=>`<a class="search-result" href="${playerUrl(id)}"><span class="player-avatar">${esc(initials(p.player_name))}</span><span><strong>${esc(p.player_name)}</strong><small>${esc(rosterMap[id]?.team_name || 'Not currently rostered')} · ${esc(rosterMap[id]?.position || 'League history')}</small></span></a>`).join(''):''}${!ts.length&&!ps.length?empty('No matches'):''}`;box.hidden=false;e.target.setAttribute('aria-expanded','true');}
function closeSearch(){const results=$('#global-results');if(results)results.hidden=true;$('#global-search')?.setAttribute('aria-expanded','false');}
function heading(title,subtitle,action='',eyebrow='DUCKS ON THE POND'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function footer(){return `<footer class="footer"><span class="brand-mini"><img src="assets/dotp-crest.png" alt=""><span>DUCKS ON THE POND</span></span><span>Fantrax league records · Fetched ${date(D.refresh_status.refreshed_at)} · ${currentYear} roster snapshot</span></footer>`;}
function standingsTable(rows=seasonRows(),compact=false){const max=Math.max(...rows.map(r=>r.pts),1);return `<div class="table-wrap"><table><thead><tr><th scope="col">#</th><th scope="col">Team</th><th scope="col">Roto pts</th><th scope="col">vs. ${year-1}</th>${compact?'':'<th scope="col">HR</th><th scope="col">RBI</th><th scope="col">SB</th><th scope="col">OBP</th><th scope="col">K</th><th scope="col">ERA</th><th scope="col">WHIP</th>'}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.owner_real_name===selectedOwner?'selected':''}"><td class="rank ${r.rank===1?'first':''}">${r.rank===1?'01':String(r.rank).padStart(2,'0')}</td><td>${teamCell(r.owner_real_name,r.season)}</td><td class="points">${fmt(r.pts)}<div class="point-meter"><span style="width:${r.pts/max*100}%"></span></div></td><td>${change(r.owner_real_name)}</td>${compact?'':`<td>${r.hr}</td><td>${r.rbi}</td><td>${r.sb}</td><td>${Number(r.obp).toFixed(3)}</td><td>${fmt(r.k)}</td><td>${Number(r.era).toFixed(2)}</td><td>${Number(r.whip).toFixed(3)}</td>`}</tr>`).join('')}</tbody></table></div>`;}
function tradeFeed(events,limit=4){return events.length?events.slice(0,limit).map(t=>`<a class="activity-item" style="display:block" href="${url('trade.html',{trade:t.event_id})}" data-trade="${esc(t.event_id)}"><div class="activity-top"><span class="pill">${esc(t.trade_type_label)}</span><time>${date(t.date_iso)}</time></div><p>${t.parties.map(p=>esc(p.split(' ').slice(-1)[0])).join(' <span class="muted">↔</span> ')}</p><div class="activity-detail">${esc(Object.values(t.assets_by_party).flatMap(p=>p.received).slice(0,3).join(' · ') || 'Draft picks / budget exchange')}</div></a>`).join(''):empty('No trades this season','Choose another season to explore league trades.');}
function trendChart(names, small=false){const rows=names.map(n=>D.standings.season_standings.filter(r=>r.owner_real_name===n).sort((a,b)=>a.season-b.season));const years=D.teams.meta.seasons;const width=560,height=small?145:210,left=30,right=20,top=18,bottom=30;const x=y=>left+(y-years[0])/(years.length-1)*(width-left-right),py=r=>top+(r-1)/11*(height-top-bottom);let svg=`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Season finishing ranks; first place is at the top">${[1,6,12].map(r=>`<line class="axis" x1="${left}" x2="${width-right}" y1="${py(r)}" y2="${py(r)}"/><text x="3" y="${py(r)+4}">${r}</text>`).join('')}${years.map(y=>`<text x="${x(y)}" y="${height-5}" text-anchor="middle">${y}</text>`).join('')}`;rows.forEach((rs,i)=>{svg+=`<polyline class="trend ${i?'gold-trend':''}" points="${rs.map(r=>`${x(r.season)},${py(r.rank)}`).join(' ')}"/>${rs.map(r=>`<circle class="dot ${i?'gold-dot':''}" cx="${x(r.season)}" cy="${py(r.rank)}" r="3.5"><title>${esc(names[i])}: ${r.season}, rank ${r.rank}, ${r.pts} points</title></circle>`).join('')}`;});svg+='</svg>';return `<div class="panel-body">${svg}<div class="legend">${names.map((n,i)=>`<span><i class="${i?'gold':''}"></i>${esc(ownerMap[n]?.current_team || n)}</span>`).join('')}</div><details class="chart-detail"><summary>View rank data</summary><div class="table-wrap"><table><thead><tr><th>Team</th>${years.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${names.map((n,i)=>`<tr><td>${esc(n)}</td>${rows[i].map(r=>`<td>${r.rank}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div>`;}
function acquisitionChart(owner){const roster=D.rosters.by_owner[owner] || [], types=[['TRADED','Trade',''],['DRAFTED','Draft','gold'],['CLAIMED','Waivers','blue'],['KEPT','Kept / other','orange']];return `<div class="panel-body"><div class="bar-chart">${types.filter(([type])=>roster.some(p=>p.acquisition_type===type)).map(([type,label,cls])=>{const n=roster.filter(p=>p.acquisition_type===type).length;return `<div class="bar-line"><span>${label}</span><div class="bar-track"><div class="bar-fill ${cls}" style="width:${n/Math.max(roster.length,1)*100}%"></div></div><strong class="num">${n}</strong></div>`;}).join('')}</div><p class="status-line">${roster.length} current roster spots · recorded acquisition method</p></div>`;}
function overview(){const standings=seasonRows(),team=ownerStanding(selectedOwner),prev=ownerStanding(selectedOwner,year-1),trades=D.trades.trade_events.filter(t=>t.year===year),champ=standings[0],delta=team&&prev?team.pts-prev.pts:null;return `${heading('League overview',`The whole league, at a glance. Your ${year} season in focus.`,`<a class="btn" href="${teamUrl(selectedOwner)}">${icon('teams')}Open my team${icon('arrow')}</a>`)}<section class="hero"><div><div class="eyebrow">THE CLUBHOUSE · EST. 2019</div><h2>Every season has a story.</h2><p>Follow the rosters. Revisit the deals. Know your league.</p><div class="hero-footer"><span>12 TEAMS</span><span>8 SEASONS</span><span>${fmt(D.teams.meta.total_trade_events)} TRADES & COUNTING</span></div></div><img class="hero-emblem" src="assets/dotp-crest.png" alt="DOTP baseball duck emblem"></section><div class="metric-row">${metric('Your standing',team?'#'+team.rank:'—',`${esc(teamName(selectedOwner))} · ${year}`,'trophy')}${metric('Roto points',team?fmt(team.pts):'—',delta==null?'No prior season':`<span class="${delta>=0?'positive':''}">${delta>=0?'+':''}${fmt(delta)} points</span> vs. ${year-1}`)}${metric('Season trades',trades.length,'Across all 12 teams','trades')}${metric('Players rostered',D.rosters.meta.total_rostered,`${currentYear} snapshot · all teams`,'players')}</div><div class="story-links"><a href="${url('standings.html')}">${icon('standings')}<span><strong>Replay the season race</strong><small>Weekly ranks, points & comebacks</small></span>${icon('arrow')}</a><a href="${url('trade.html')}">${icon('trades')}<span><strong>Follow the trade routes</strong><small>Partners, players & where they landed</small></span>${icon('arrow')}</a><a href="${url('drafts.html')}">${icon('drafts')}<span><strong>Revisit the draft</strong><small>Late-round keepers & class grades</small></span>${icon('arrow')}</a></div><div class="grid-main"><div class="stack">${panel('League standings',`${year} results · rotisserie points`,standingsTable(standings,true)+`<div class="panel-foot"><span>↑ ↓ Rank change from the previous season</span><span>Highlighted: your team</span></div>`,link('Full standings',url('standings.html')))}${panel('The long game',`${esc(ownerMap[selectedOwner]?.current_team)} · season finishing positions`,trendChart([selectedOwner],true),link('Team history',url('team.html',{owner:selectedOwner,tab:'history'})))}</div><div class="stack overview-side">${panel('Latest trades',`${year} · most recent first`,tradeFeed(trades),link('View all',url('trade.html')))}${panel('Your roster, built over time',esc(ownerMap[selectedOwner]?.current_team),acquisitionChart(selectedOwner),link('Roster',teamUrl(selectedOwner)))}${panel(`${year} league leader`,'Highest recorded rotisserie points',`<div class="panel-body">${teamCell(champ.owner_real_name)}<div style="display:flex;align-items:baseline;gap:10px;margin-top:15px"><strong style="font-size:30px;font-family:Manrope">${champ.pts}</strong><span class="muted small">roto points</span></div></div>`)}</div></div>`;}
function pagination(total){const pages=Math.max(1,Math.ceil(total/pageSize));page=Math.min(page,pages);return `<div class="pagination"><span>${total?`${(page-1)*pageSize+1}–${Math.min(page*pageSize,total)} of ${fmt(total)}`:'0 results'}</span><div class="buttons"><button class="btn" data-page-step="-1" ${page<=1?'disabled':''}>Previous</button><span style="align-self:center">${page} / ${pages}</span><button class="btn" data-page-step="1" ${page>=pages?'disabled':''}>Next</button></div></div>`;}
function tableControls({team=false}={}){return `<div class="toolbar"><div class="search-field">${icon('search')}<input id="player-filter" type="search" placeholder="Find a player…" aria-label="Filter players" value="${esc(param('q'))}"></div>${!team?`<select id="owner-filter" aria-label="Filter by team">${ownerOptions(param('filterOwner'),true)}</select>`:''}<select id="status-filter" aria-label="Filter roster status"><option value="">All statuses</option>${['ACTIVE','MINORS','RESERVE','IR','UNROSTERED'].map(s=>`<option value="${s}" ${param('status')===s?'selected':''}>${s==='UNROSTERED'?'Not rostered':s==='IR'?'Injured reserve':s.charAt(0)+s.slice(1).toLowerCase()}</option>`).join('')}</select><select id="position-filter" aria-label="Filter position"><option value="">All positions</option>${['C','1B','2B','3B','SS','OF','SP','RP','UT'].map(p=>`<option ${param('position')===p?'selected':''}>${p}</option>`).join('')}</select><button class="btn" data-reset>Reset</button></div>`;}
function playerTable(rows){tableRows=rows;const q=normal(param('q')),owner=param('filterOwner'),status=param('status'),position=param('position');let filtered=rows.filter(p=>normal(p.player_name).includes(q)&&(!owner||p.owner_real_name===owner)&&(!status||(p.roster_status||'UNROSTERED')===status)&&(!position||String(p.position).split(',').map(s=>s.trim()).includes(position)));filtered.sort((a,b)=>{const av=a[sortKey]??'',bv=b[sortKey]??'';return (typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv)))*sortDirection;});const pager=pagination(filtered.length);const subset=filtered.slice((page-1)*pageSize,page*pageSize);const th=(key,label)=>`<th scope="col" aria-sort="${sortKey===key?(sortDirection===1?'ascending':'descending'):'none'}"><button class="sort-button" data-sort="${key}">${label}<span class="sort-arrow">${sortKey===key?(sortDirection===1?'↑':'↓'):'↕'}</span></button></th>`;return `<div class="table-wrap"><table><thead><tr>${th('player_name','Player')}${th('position','Pos')}<th scope="col">Current team</th>${th('roster_status','Status')}${th('acquisition_type','Acquired via')}${th('stint_start','Since')}<th>Explore</th></tr></thead><tbody>${subset.map(p=>`<tr><td>${playerLink(p.player_id,p.player_name)}</td><td><span class="pill">${esc(p.position||'—')}</span></td><td>${p.owner_real_name?`<a href="${teamUrl(p.owner_real_name)}" class="text-link">${esc(ownerMap[p.owner_real_name]?.current_team||p.owner_real_name)}</a>`:'<span class="muted">Not rostered</span>'}</td><td>${p.roster_status?`<span class="pill ${esc(p.roster_status)}">${esc(p.roster_status)}</span>`:'—'}</td><td>${esc(p.acquisition_type?.toLowerCase()||'—')}</td><td class="muted">${p.stint_start?date(p.stint_start):'—'}</td><td><div class="row-actions"><button class="text-link" data-player="${esc(p.player_id)}">Details</button><a class="journey-link" href="${playerUrl(p.player_id)}">Journey</a><button class="expand-button" data-expand-player="${esc(p.player_id)}" aria-expanded="false" aria-label="Expand ${esc(p.player_name)} ownership history">${icon('chevron')}</button></div></td></tr>`).join('')}</tbody></table></div>${!subset.length?empty('No players match these filters'):''}${pager}`;}
function allPlayers(){return Object.entries(playerMap).map(([id,p])=>({...p,player_id:id,...(rosterMap[id]||{})}));}
function players(){return `${heading('Player explorer','Click a player name or Journey to explore their history. Details opens a quick view; the chevron expands it inline.',`<span class="pill">${fmt(Object.keys(playerMap).length)} players</span>`)}<div class="roster-key"><span class="fresh-dot"></span>Current ownership: ${currentYear} snapshot · history spans 2019–${currentYear}</div><div class="journey-suggestions"><span>JOURNEYS TO EXPLORE</span>${D.journeys.most_traveled_players.slice(0,3).map(p=>`<a href="${playerUrl(p.player_id)}">${esc(p.player_name)} <small>${p.distinct_owners} owners</small>${icon('arrow')}</a>`).join('')}</div>${tableControls()}<section class="panel" id="player-results">${playerTable(allPlayers())}</section>`;}
function categoryRanks(owner){const rows=seasonRows(), own=rows.find(r=>r.owner_real_name===owner);if(!own)return [];return ['r','hr','rbi','sb','obp','k','era','whip','svh3','wqs'].map(key=>{const lower=['era','whip'].includes(key);const better=rows.filter(r=>lower?r[key]<own[key]:r[key]>own[key]).length;return {key,label:({svh3:'SVH3',wqs:'W+QS'})[key]||key.toUpperCase(),rank:better+1,value:own[key]};});}
function categoryChart(owner){return `<div class="panel-body"><div class="category-bars">${categoryRanks(owner).map(c=>`<div class="category-row"><span>${c.label}</span><div class="bar-track"><div class="bar-fill" style="width:${(13-c.rank)/12*100}%;background:${rankColor(c.rank)}"></div></div><strong>#${c.rank}</strong></div>`).join('')}</div>${rankLegend()}<p class="status-line">Rank among 12 teams · longer is better · ties share rank</p></div>`;}
function teams(){const requested=param('owner');if(!ownerMap[requested])return `${heading('The teams','Twelve teams. Eight seasons of rivalries and roster building.')}<div class="team-grid">${owners.map(o=>{const s=ownerStanding(o.real_name);return `<a class="team-card" href="${teamUrl(o.real_name)}">${badge(o.real_name,true)}<h2>${esc(teamName(o.real_name))}</h2><p class="muted small">${esc(o.real_name)}</p><div class="card-stats"><span><strong>#${s?.rank||'—'}</strong>${year} rank</span><span><strong>${s?.pts??'—'}</strong>Roto points</span><span><strong>${D.rosters.by_owner[o.real_name]?.length||0}</strong>Current players</span></div></a>`;}).join('')}</div>`;
 const o=ownerMap[requested],s=ownerStanding(requested),tab=param('tab','roster'),roster=D.rosters.by_owner[requested]||[],trades=D.trades.trade_events.filter(t=>t.parties.includes(requested)&&t.year===year);let content;
 if(tab==='performance'){const other=param('compare');content=`<div class="grid-two">${panel('Category strengths',`${year} · ranking within the league`,categoryChart(requested))}${panel('Season finishes','First place at the top · 2019–2026',trendChart([requested,...(ownerMap[other]&&other!==requested?[other]:[])]))}</div><div class="section-space">${panel('Compare teams','Choose another owner to compare recorded season results',`<div class="panel-body"><label class="select-label">Compare against<select id="compare-owner"><option value="">Choose a team</option>${ownerOptions(other).replace(new RegExp(`<option value="${esc(requested)}"[^>]*>[^<]*</option>`),'')}</select></label></div>${ownerMap[other]?standingsTable(seasonRows().filter(r=>[requested,other].includes(r.owner_real_name))):''}`)}</div>`;}
 else if(tab==='trades'){content=panel(`${year} trades`,`${trades.length} trades involving ${esc(o.current_team)}`,tradeList(trades),link('Open explorer',url('trade.html',{filterOwner:requested})));}
 else if(tab==='history'){content=`<div class="grid-two">${panel('The long game','Season finishing position',trendChart([requested]))}${panel('A franchise through the years','Same owner. A few different names.',`<div class="panel-body"><ol class="timeline">${o.history.slice().reverse().map(h=>{const r=ownerStanding(requested,h.season);return `<li><time>${h.season}</time><strong>${esc(h.team_name)}</strong><p>Finished #${r?.rank||'—'} · ${r?.pts??'—'} roto points</p></li>`;}).join('')}</ol></div>`)}</div>`;}
 else {content=`${year!==currentYear?`<div class="notice">Showing the current ${currentYear} roster. The selected ${year} season applies to performance, trades, and historical team names.</div>`:''}<div class="roster-key"><span class="fresh-dot"></span>${roster.length} players · ${currentYear} roster snapshot</div>${tableControls({team:true})}<section class="panel" id="player-results">${playerTable(roster)}</section><div class="grid-two section-space">${panel('How this roster came together','Acquisition method of current players',acquisitionChart(requested))}${panel('Season finishes','An eight-season view',trendChart([requested],true))}</div>`;}
 return `<div class="team-heading">${badge(requested,true)}<div><div class="eyebrow muted">TEAM CLUBHOUSE</div><h1>${esc(teamName(requested))}</h1><p>${esc(requested)} · Member since 2019</p></div><select class="team-switch" id="team-switch" aria-label="Switch team">${ownerOptions(requested)}</select></div><div class="metric-row">${metric(`${year} standing`,s?'#'+s.rank:'—','of 12 teams','trophy')}${metric('Roto points',s?fmt(s.pts):'—',`${year} season results`)}${metric('Current roster',roster.length,`${currentYear} snapshot`,'players')}${metric('Season trades',trades.length,`${year} · ${o.stats.total_trades} all-time`,'trades')}</div><nav class="tabs" aria-label="Team sections">${['roster','performance','trades','history'].map(t=>`<a class="tab ${tab===t?'active':''}" href="${url('team.html',{owner:requested,tab:t})}" ${tab===t?'aria-current="page"':''}>${({roster:'Roster',performance:'Performance & compare',trades:'Trades',history:'Franchise history'})[t]}</a>`).join('')}</nav>${content}`;
}
function playerProfile(id,full=false){const p=playerMap[id];if(!p)return empty('Player not found','Return to the player explorer and choose a player.');const r=rosterMap[id],stints=(stintsByPlayer[id]||[]).slice().sort((a,b)=>b.start_date.localeCompare(a.start_date));const timeline=`<ol class="timeline">${stints.map(s=>`<li><time>${date(s.start_date)} → ${s.is_current?'Present':s.end_date_unknown?'End date unavailable':date(s.end_date)}</time><strong><a href="${teamUrl(s.owner_real_name)}">${esc(s.team_name)}</a></strong><span class="pill ${esc(s.acquisition_type)}">${esc(s.acquisition_type.toLowerCase())}</span><p>${esc(s.owner_real_name)}${s.tenure_days!=null?` · ${fmt(s.tenure_days)} days`:''}</p></li>`).join('')}</ol>`;
 const profile=`<div class="profile-top"><span class="player-avatar big">${esc(initials(p.player_name))}</span><div><h2>${esc(p.player_name)}</h2><p>${esc(r?.position||'Historical player')} ${r?`· <span class="pill ${r.roster_status}">${esc(r.roster_status)}</span>`:''}</p></div></div><div class="mini-title"><span class="muted small">Current owner · ${currentYear}</span></div>${r?teamCell(r.owner_real_name,currentYear):'<p class="muted small">Not currently rostered in this league.</p>'}<div class="profile-stats"><div><strong>${p.distinct_owners}</strong><span>Distinct owners</span></div><div><strong>${p.owner_changes}</strong><span>Owner changes</span></div><div><strong>${stints.length}</strong><span>Recorded stints</span></div></div>`;
 const related=D.trades.trade_events.filter(t=>Object.values(t.assets_by_party).some(a=>a.received.includes(p.player_name)||a.sent.includes(p.player_name)));
 if(!full)return `${profile}<div class="mini-title"><h3>Ownership journey</h3>${`<a class="btn journey-link" href="${playerUrl(id)}">Explore player journey ${icon('arrow')}</a>`}</div>${timeline}`;
 return `${heading(esc(p.player_name),'The complete league journey, from first acquisition to today.',`<a class="btn" href="${url('player_history.html')}">${icon('players')}All players</a>`)}${journeyReplay(id)}<div class="player-layout section-space">${panel('Ownership journey','Newest acquisition first',`<div class="panel-body">${timeline}</div>`)}<div class="stack">${panel('Player snapshot','Current league ownership',`<div class="panel-body">${profile}</div>`)}${panel('Related trades','Matched by recorded player name',tradeFeed(related,6))}</div></div>`;
}
function productionData(){return D.trade_production_2026;}
function productionBadge(side){const provisional=side.grade&&productionData()?.audit.some(a=>a.owner===side.owner&&Object.values(a.differences).some(v=>v!==0));return `<span class="grade grade-${side.grade||'none'}" title="${provisional?'Provisional: team season totals have a coverage gap':'Received counting-production grade'}">${side.grade||'—'}${provisional?'*':''}</span>`;}
function tradeGradeSummary(t){const e=productionData()?.events[t.event_id];return e?`<div class="trade-grade-list">${e.sides.map(s=>`<a class="text-link" href="${url('trade.html',{trade:t.event_id})}" data-trade="${esc(t.event_id)}" title="${esc(s.owner)} · ${s.grade?'received production grade '+s.grade:s.players.length?'incomplete player coverage':'no received players to grade'}">${productionBadge(s)} ${esc(s.owner.split(' ').slice(-1)[0])}</a>`).join('')}</div>`:'<span class="muted small">Not collected</span>';}
function productionOverview(){const d=productionData();if(!d||year!==d.season)return `<div class="notice">Production return grades are available for 2026. Earlier seasons have not been collected.</div>`;const clean=d.audit.filter(a=>Object.values(a.differences).every(v=>v===0)).length;const sides=Object.entries(d.events).flatMap(([id,e])=>e.sides.filter(s=>s.grade).map(s=>({...s,id,date:e.date}))).sort((a,b)=>b.score-a.score).slice(0,3);return panel('Trade production grades',`${year} · what received players actually added to the lineup`, `<div class="panel-body"><p class="production-intro">A first look at the production returned by each side of a deal. <strong>${d.rated_sides} receiving sides rated</strong> · ${clean} of ${d.audit.length} team totals reconcile across all seven counting categories.</p><div class="production-leaders">${sides.map(s=>`<a class="production-leader" href="${url('trade.html',{trade:s.id})}" data-trade="${esc(s.id)}"><div>${productionBadge(s)}<span>${esc(teamName(s.owner))}<small>${date(s.date)}</small></span>${icon('arrow')}</div><p>${esc(s.players.map(p=>p.player_name).join(' · '))}</p><strong>${fmt(s.totals.hr)} HR <span>·</span> ${fmt(s.totals.k)} K <span>·</span> ${fmt(s.totals.svh3)} SVH3</strong></a>`).join('')}</div><p class="status-line">Grades appear beside every deal below. * marks a team with incomplete season reconciliation. Open Details for player stats and the exact dates counted.</p><details class="raw-details"><summary>How grades work & data coverage</summary><p>A = top quarter, B = next quarter, then C and D among fully covered receiving sides. Zero recorded production earns D. Seven counting categories contribute equally after scaling to a typical team’s season totals. Longer ownership windows have more opportunity.</p><p>These are <strong>received-production grades, not overall trade-value grades</strong>. Picks, budget, outgoing cost, future value and rate categories are not scored. Missing players or values are never filled with zero. Trade and departure days are omitted to avoid uncertain timing; later reacquisitions are excluded.</p><p>Source: Fantrax Full Fantasy Team statistics, including departed players. Player rates are displayed as reported, never averaged.</p>${d.audit.filter(a=>Object.values(a.differences).some(v=>v!==0)).map(a=>`<p><strong>${esc(teamName(a.owner))}: incomplete season reconciliation.</strong> ${Object.entries(a.differences).filter(([,v])=>v!==0).map(([k,v])=>`${k.toUpperCase()}: ${v>0?'+':''}${v} vs standings`).join(' · ')}. Available player records remain visible; no balancing values are invented.</p>`).join('')}</details></div>`,'','section-space production-panel');}
function productionDetail(t){const d=productionData(),e=d?.events[t.event_id];if(!e)return `<div class="notice">Production grades have not been collected for this season.</div>`;const labels={r:'R',hr:'HR',rbi:'RBI',sb:'SB',obp:'OBP',k:'K',svh3:'SVH3',wqs:'W+QS',ip:'IP',era:'ERA',whip:'WHIP',gp:'Games'};return `<section class="production-detail"><h3>Production after the deal</h3><p class="muted small">Same-season fantasy-lineup production · full days after acquisition and before departure. Rates shown per player; grades use seven counting categories only.</p>${e.sides.map(s=>`<div class="production-side"><div class="production-side-heading">${productionBadge(s)}<div><strong>${esc(teamName(s.owner,t.year))}</strong><small>${s.grade?'Received-production grade · '+s.percentile+'th percentile':s.players.length?'Not graded — incomplete coverage':'No received players to grade'} · ${s.available}/${s.players.length} player records available</small></div></div>${s.players.map(p=>`<article class="production-player"><div>${p.player_id?`<a class="text-link" href="${playerUrl(p.player_id)}">${esc(p.player_name)}</a>`:esc(p.player_name)}<small>${p.start&&p.start<=p.end?`${date(p.start)} – ${date(p.end)}`:'No verified scoring window'}</small></div>${p.status==='available'?Object.entries(p.groups).map(([group,stats])=>`<div class="production-stats" aria-label="${group} statistics">${(group==='hitting'?['gp','r','hr','rbi','sb','obp']:['gp','ip','k','svh3','wqs','era','whip']).map(k=>`<span><small>${labels[k]}</small><b>${stats[k]==null||(['obp','era','whip'].includes(k)&&stats.gp===0)?'—':esc(['obp','whip'].includes(k)?Number(stats[k]).toFixed(3):k==='era'?Number(stats[k]).toFixed(2):stats[k])}</b></span>`).join('')}</div>`).join(''):`<p class="muted small">${esc(p.reason)}. Missing, not zero.</p>`}</article>`).join('')||'<p class="muted small">Picks and budget are not valued in this production view.</p>'}${d.audit.some(a=>a.owner===s.owner&&Object.values(a.differences).some(v=>v!==0))?'<p class="coverage-note">This team’s season totals have a reconciliation gap. Individual source records are shown as returned; this grade may have incomplete coverage.</p>':''}</div>`).join('')}<p class="status-line">A/B/C/D compare received counting production with other fully covered sides this season. They do not value outgoing assets, rates, picks, budget or future production.</p></section>`;}

function tradeList(events){const pager=pagination(events.length);return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Teams</th><th>Players involved</th><th>Return grades</th><th>Type</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${events.slice((page-1)*pageSize,page*pageSize).map(t=>`<tr><td class="muted" style="white-space:nowrap">${date(t.date_iso)}</td><td>${t.parties.map(p=>`<a class="text-link" href="${teamUrl(p)}">${esc(p.split(' ').slice(-1)[0])}</a>`).join(' <span class="muted"> / </span> ')}</td><td>${esc(Object.values(t.assets_by_party).flatMap(p=>p.received).join(', ')||'Picks / budget')} ${t.pick_assets.length?`<span class="pill">${t.pick_assets.length} pick${t.pick_assets.length===1?'':'s'}</span>`:''}</td><td>${tradeGradeSummary(t)}</td><td><span class="pill">${esc(t.trade_type_label)}</span></td><td><a class="text-link" href="${url('trade.html',{trade:t.event_id})}" data-trade="${esc(t.event_id)}">Details</a><details class="trade-inline"><summary aria-label="Expand trade from ${date(t.date_iso)}">${icon('chevron')}</summary><div>${t.parties.map(owner=>`<p><strong>${esc(teamName(owner,t.year))}</strong><br>Received: ${esc(t.assets_by_party[owner].received.join(', ')||'Picks / budget')}</p>`).join('')}<p>${esc(t.details_raw)}</p></div></details></td></tr>`).join('')}</tbody></table></div>${events.length?'':empty('No matching trades')}${pager}`;}
function filteredTrades(){return D.trades.trade_events.filter(t=>t.year===year&&(!param('filterOwner')||t.parties.includes(param('filterOwner')))&&(!param('partner')||t.parties.includes(param('partner')))&&(!param('type')||t.trade_type_label===param('type'))&&(!param('month')||t.month_num===Number(param('month')))&&normal(t.details_raw).includes(normal(param('q'))));}
function trades(){const types=[...new Set(D.trades.trade_events.map(t=>t.trade_type_label))].sort();return `${heading('Trade explorer','The deals that shaped the league. Find the story behind every exchange.',`<button class="btn yellow-btn" data-clear-trades>Show all trades</button>`)}${productionOverview()}<div class="grid-two section-space">${routePanel()}<div class="stack">${panel('Trading calendar',`${year} · click a month to filter the deals`,monthlyChart())}${panel('Most active owners',`${year} · each party counts as one participation`,tradeBars())}</div></div><h2 class="section-space">Explore the deals</h2><div id="trade-summary">${tradeSummary()}</div><div class="toolbar"><div class="search-field">${icon('search')}<input id="trade-filter" type="search" aria-label="Search trades" placeholder="Search players or trade details…" value="${esc(param('q'))}"></div><select id="trade-owner" aria-label="Filter trading team">${ownerOptions(param('filterOwner'),true)}</select><select id="trade-partner" aria-label="Filter trade partner"><option value="">Any trade partner</option>${ownerOptions(param('partner'))}</select><select id="trade-type" aria-label="Filter asset type"><option value="">All trade types</option>${types.map(t=>`<option ${param('type')===t?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="btn" data-reset>Reset</button></div>${param('month')?`<p class="filter-note">Month filter: ${new Date(year,Number(param('month'))-1,1).toLocaleString('en-US',{month:'long'})} · click the selected calendar month to clear</p>`:''}<section class="panel" id="trade-results">${tradeList(filteredTrades())}</section>`;}
function monthlyChart(){const counts=Array.from({length:12},(_,i)=>D.trades.trade_events.filter(t=>t.year===year&&t.month_num===i+1).length),max=Math.max(...counts,1);return `<div class="panel-body"><div class="month-chart">${counts.map((n,i)=>`<button type="button" class="month-column" data-trade-month="${i+1}" aria-pressed="${Number(param('month'))===i+1}" aria-label="Filter ${new Date(year,i,1).toLocaleString('en-US',{month:'long'})}: ${n} trades"><strong>${n}</strong><span class="month-space"><i style="height:${n/max*100}%"></i></span><small>${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]}</small></button>`).join('')}</div><p class="status-line">All executed trades in ${year}. Select a month to explore its deals below.</p></div>`;}
function tradeBars(){const counts=owners.map(o=>({name:o.real_name,n:D.trades.trade_events.filter(t=>t.year===year&&t.parties.includes(o.real_name)).length})).sort((a,b)=>b.n-a.n).slice(0,5),max=Math.max(...counts.map(c=>c.n),1);return `<div class="panel-body"><div class="bar-chart">${counts.map(c=>`<a href="${url('trade.html',{filterOwner:c.name})}" class="bar-line"><span>${esc(c.name.split(' ').slice(-1)[0])}</span><div class="bar-track"><div class="bar-fill" style="width:${c.n/max*100}%"></div></div><strong>${c.n}</strong></a>`).join('')}</div></div>`;}
function tradeDetail(id){const t=D.trades.trade_events.find(t=>t.event_id===id);if(!t)return empty('Trade not found');return `<p class="muted small">${date(t.date_iso)} · ${esc(t.trade_type_label)}</p><div class="trade-sides" style="--parties:${t.parties.length}">${t.parties.map(p=>{const assets=t.assets_by_party[p];const picks=t.pick_assets.filter(k=>k.receiving_owner===p);return `<section class="trade-side">${teamCell(p,t.year)}<div class="eyebrow">RECEIVED</div><ul>${assets.received.map(name=>`<li>${assetPlayer(name)}</li>`).join('')}${picks.map(k=>`<li>${k.pick_year} round ${k.pick_round}${k.pick_in_round?`, pick ${k.pick_in_round}`:''} <span class="muted small">(${esc(k.original_holder || 'original owner unknown')})</span></li>`).join('')}${!assets.received.length&&!picks.length?'<li class="muted">See the source record for budget assets.</li>':''}</ul><div class="eyebrow">PLAYERS SENT</div><ul>${assets.sent.map(name=>`<li>${assetPlayer(name)}</li>`).join('')||'<li class="muted">No players</li>'}</ul></section>`;}).join('')}</div>${productionDetail(t)}${tradeOutcomes(t)}<details class="raw-details"><summary>Complete source record · includes budget amounts</summary><p>${esc(t.details_raw)}</p></details>`;}
function assetPlayer(name){const matches=Object.entries(playerMap).filter(([,p])=>p.player_name===name);return matches.length===1?`<a href="${playerUrl(matches[0][0])}" class="text-link">${esc(name)}</a>`:esc(name);}
function standings(){return `${heading('League standings',`${year} season results. Explore category strengths and compare the field.`)}${weeklyRace()}<div class="section-space"></div>${panel('The leaderboard','Recorded Fantrax rotisserie standings',standingsTable())}<div class="section-space">${panel('Category strengths','Rank within this season · green leads, terracotta trails',heatmap())}</div>`;}
function heatmap(){const cats=['R','HR','RBI','SB','OBP','K','ERA','WHIP','SVH3','W+QS'];return `${rankLegend()}<div class="table-wrap"><table class="heat-table"><thead><tr><th>Team</th>${cats.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${seasonRows().map(r=>`<tr><td>${teamCell(r.owner_real_name)}</td>${categoryRanks(r.owner_real_name).map(c=>`<td><span class="heat-cell" style="background:${rankColor(c.rank)};color:${rankInk(c.rank)}" title="${c.label}: ${c.value}; rank ${c.rank}">${c.rank}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-foot">Lower ERA and WHIP rank better. Ties share rank. These are category ranks, not player valuations.</div>`;}
function drafts(){const season=D.draft_results.seasons.find(s=>s.year===year);return `${heading('Draft room',`${year} draft · ${season?.num_rounds||0} rounds · follow each pick into its league journey.`)}${draftStories()}${draftCompare()}<h2 class="section-space">Every selection</h2><div class="toolbar"><div class="search-field">${icon('search')}<input id="draft-filter" type="search" aria-label="Search draft selections" placeholder="Find a drafted player…" value="${esc(param('q'))}"></div><select id="draft-owner" aria-label="Filter drafting team">${ownerOptions(param('filterOwner'),true)}</select><button class="btn" data-reset>Reset</button></div><section class="panel" id="draft-results">${draftTable()}</section><div class="section-space">${panel('Traded pick outcomes',`${year} draft picks that appeared in recorded trades`,pickTable())}</div>${draftRankings()}`;}
function draftTable(){const picks=(D.draft_results.seasons.find(s=>s.year===year)?.picks || []).filter(p=>(!param('filterOwner')||p.owner_name===param('filterOwner'))&&normal(p.player_name).includes(normal(param('q'))));const pager=pagination(picks.length);return `<div class="table-wrap"><table><thead><tr><th>Overall</th><th>Pick</th><th>Player</th><th>Drafted by</th><th>Current owner</th></tr></thead><tbody>${picks.slice((page-1)*pageSize,page*pageSize).map(p=>`<tr><td class="points">${p.overall_pick}</td><td class="muted">${p.round}.${String(p.pick_in_round).padStart(2,'0')}</td><td>${p.pick_status==='selected'?playerLink(p.player_id,p.player_name):'<span class="muted">Unfilled slot</span>'}</td><td>${teamCell(p.owner_name,year)}</td><td>${rosterMap[p.player_id]?`<a class="text-link" href="${teamUrl(rosterMap[p.player_id].owner_real_name)}">${esc(rosterMap[p.player_id].team_name)}</a>`:'<span class="muted">Not rostered</span>'}</td></tr>`).join('')}</tbody></table></div>${picks.length?'':empty('No matching draft selections')}${pager}`;}
function pickTable(){const picks=D.picks.pick_results.filter(p=>p.pick_year===year);return `<div class="panel-body"><p class="muted small">${picks.length} traded-pick references. A player is confirmed only when the source specifies an exact draft slot.</p></div><div class="table-wrap" style="max-height:340px"><table><thead><tr><th>Pick</th><th>Received by</th><th>Outcome</th></tr></thead><tbody>${picks.map(p=>`<tr><td>Round ${p.pick_round}${p.pick_in_round?` · Pick ${p.pick_in_round}`:''}</td><td><a href="${teamUrl(p.receiving_owner)}" class="text-link">${esc(p.receiving_owner)}</a></td><td>${p.result_status==='matched'?`<span class="pill">Confirmed</span> ${esc(typeof p.drafted_player==='object'?p.drafted_player?.player_name:p.drafted_player)}`:`<span class="pill">${({ambiguous:'Unresolved · multiple candidates',unknown:'Unknown',pending:'Future pick'})[p.result_status]||esc(p.result_status)}</span>`}</td></tr>`).join('')}</tbody></table></div>`;}
function leagueHistory(){const champions=D.teams.meta.seasons.slice().reverse().map(y=>seasonRows(y)[0]);return `${heading('League history','Eight seasons of champions, rivalries, and changing team names.')}<div class="metric-row">${metric('Seasons',8,'2019–2026','calendar')}${metric('Trades',fmt(D.trades.meta.total_trade_events),'All recorded executed trades','trades')}${metric('Players',fmt(D.journeys.meta.total_unique_players),'Historical league players','players')}${metric('Draft selections',fmt(D.refresh_status.selected_draft_slots),'Across eight drafts','drafts')}</div>${historyRace()}<div class="grid-main section-space"><div class="stack">${panel('The pennant collection','Top recorded rotisserie finish each season',`<div class="table-wrap"><table><thead><tr><th>Season</th><th>First place</th><th>Points</th></tr></thead><tbody>${champions.map(c=>`<tr><td><a class="text-link" href="standings.html?season=${c.season}">${c.season}</a></td><td>${teamCell(c.owner_real_name,c.season)}</td><td class="points">${c.pts}</td></tr>`).join('')}</tbody></table></div>`)}${panel('All-time leaderboard','Cumulative season points · 2019–2026',`<div class="table-wrap"><table><thead><tr><th>#</th><th>Owner</th><th>Total points</th><th>Best finish</th></tr></thead><tbody>${D.standings.alltime_standings.map(o=>`<tr><td>${o.alltime_rank}</td><td>${teamCell(o.owner_real_name,currentYear)}</td><td class="points">${o.total_pts}</td><td>#${o.best_rank}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="stack">${panel('Most traveled players','Distinct owners across recorded league history',`<div class="table-wrap"><table><thead><tr><th>Player</th><th>Owners</th></tr></thead><tbody>${D.journeys.most_traveled_players.slice(0,10).map(p=>`<tr><td>${playerLink(p.player_id,p.player_name)}</td><td>${p.distinct_owners}</td></tr>`).join('')}</tbody></table></div>`)}${panel('About the records','A little context behind the numbers',`<div class="panel-body"><p class="small muted">Executed, non-deleted transactions and recorded drafts from 2019–2026. Current ownership is checked against the ${currentYear} roster snapshot.</p><p class="small muted" style="margin-top:12px">Twelve historical ownership stints have no recorded end date. Unresolved pick outcomes stay labeled as unresolved.</p></div>`)}</div></div>`;}
// Story views: cumulative standings, explicit trade routes, and draft staying power.
const rankColors=['#123d2a','#24563a','#3b704d','#4c7b55','#7fa578','#b2c39a','#e1d7b3','#dfbd91','#d4976c','#ae5f3f','#9e4c34','#793021'];
const rankColor=rank=>rankColors[Math.max(0,Math.min(11,rank-1))];
const rankInk=rank=>rank<=4||rank>=10?'#ffffff':'#202d22';
function rankLegend(){return `<div class="rank-legend"><strong>1 · strongest</strong><div>${rankColors.map((c,i)=>`<span style="background:${c};color:${rankInk(i+1)}">${i+1}</span>`).join('')}</div><strong>12 · weakest</strong></div>`;}
function weeklyRace(){
 const season=D.weekly_standings?.seasons?.[year];
 if(!season)return panel('The season race','Weekly standings',empty('Weekly history hasn’t been collected for this season','Switch to 2025 or 2026 to replay the race. Season totals are shown below.'));
 const focus=ownerMap[param('raceOwner')]?param('raceOwner'):selectedOwner,other=ownerMap[param('raceCompare')]?param('raceCompare'):seasonRows().find(r=>r.owner_real_name!==focus)?.owner_real_name,metric=raceMetrics[param('raceMetric')]?param('raceMetric'):'rank';
 return panel('The season race',`${year} · cumulative production through each scoring period`, `<div class="panel-body"><div class="race-chart-layout"><div id="race-chart">${weeklyPlot(season,focus,other,metric)}</div><aside class="race-units" aria-label="Category chart units"><span>CATEGORY VIEW</span><button type="button" data-race-units="roto" aria-pressed="${param('raceUnits','roto')!=='raw'}">Roto points</button><button type="button" data-race-units="raw" aria-pressed="${param('raceUnits')==='raw'}">Raw stats</button><small>Applies to individual categories</small></aside></div><div class="scrub-control"><label for="race-week">Scoring period</label><input type="range" id="race-week" min="0" max="${season.weeks.length-1}" value="${weekIndex(season)}"><output id="race-week-label" for="race-week">${esc(season.weeks[weekIndex(season)].label)}</output></div><div class="story-controls controls-bottom"><label for="race-scope">View<select id="race-scope"><option value="compare">Compare two teams</option><option value="all" ${param('raceScope')==='all'?'selected':''}>All 12 teams</option></select></label><label for="race-owner">Follow a team<select id="race-owner">${ownerOptions(focus)}</select></label><label for="race-compare">Compare with<select id="race-compare">${ownerOptions(other)}</select></label><label for="race-metric">Category / chart<select id="race-metric">${Object.entries(raceMetrics).map(([key,label])=>`<option value="${key}" ${metric===key?'selected':''}>${label}</option>`).join('')}</select></label></div><div id="race-story" aria-live="polite">${raceStory(season,focus,other,metric)}</div><p class="status-line" id="race-units-note">${raceUnitsNote(metric)}</p><details class="chart-detail"><summary>Weekly data table</summary><div id="race-data">${raceData(season,metric)}</div></details></div>`,'','race-panel');
}
function weekIndex(season){const n=Number(param('week',season.weeks.length-1));return Number.isFinite(n)?Math.max(0,Math.min(season.weeks.length-1,Math.floor(n))):season.weeks.length-1;}
function weeklyPlot(season,focus,other,metric){
 const weeks=season.weeks,index=weekIndex(season),W=760,H=290,L=52,R=24,T=20,B=34,all=param('raceScope')==='all';
 const vals=weeks.flatMap(w=>w.rows.map(r=>raceValue(r,metric))).filter(v=>v!=null&&Number.isFinite(v));if(!vals.length)return empty('No category data for this season');
 const roto=raceIsRoto(metric),rate=!roto&&['era','whip','obp'].includes(metric),rawMax=Math.max(...vals)||1,unit=10**Math.floor(Math.log10(rawMax/4)),niceStep=([1,1.5,2,2.5,3,4,5,6,8,10].find(n=>n*unit>=rawMax/4)||10)*unit,min=metric==='rank'?1:roto?Math.min(1,...vals):rate?Math.max(0,Math.min(...vals)*.95):0,max=metric==='rank'||roto?12:metric==='pts'?120:rate?rawMax*1.05:niceStep*4;
 const x=i=>L+i/Math.max(1,weeks.length-1)*(W-L-R),y=n=>T+(metric==='rank'?(n-1)/11:(max-n)/(max-min))*(H-T-B);
 const ticks=metric==='rank'?[1,3,6,9,12]:roto?[min,3,6,9,12]:Array.from({length:5},(_,i)=>min+(max-min)*i/4);
 const color=owner=>all?raceColors[owners.findIndex(o=>o.real_name===owner)%12]:owner===focus?'#1d5438':'#b47a00';
 const line=(owner,stroke,width,dash='')=>{let path='',active=false;weeks.forEach((w,i)=>{const v=raceValue(w.rows.find(r=>r.owner===owner),metric);if(v==null){active=false;return;}path+=`${active?'L':'M'}${x(i)},${y(v)} `;active=true;});return `<path fill="none" stroke="${stroke}" stroke-width="${width}" ${dash?'stroke-dasharray="'+dash+'"':''} stroke-linejoin="round" d="${path}"/>`;};
 const names=all?owners.map(o=>o.real_name):[...new Set([focus,other])];
 return `<div class="chart-caption">${esc(raceLabel(metric))}${!roto&&['era','whip'].includes(metric)?' · lower is better':''}</div><div class="chart-scroll"><svg viewBox="0 0 ${W} ${H}" class="race-svg" role="img" aria-label="${year} weekly ${esc(raceLabel(metric))}, ${all?'all 12 teams':esc(focus)+' compared with '+esc(other)}">${ticks.map(t=>`<line class="axis" x1="${L}" x2="${W-R}" y1="${y(t)}" y2="${y(t)}"/><text x="3" y="${y(t)+4}">${metric==='rank'?t:raceNumber(t,metric)}</text>`).join('')}${!all?owners.filter(o=>!names.includes(o.real_name)).map(o=>line(o.real_name,'#d5d9cf',1.2)).join(''):''}${names.map((n,i)=>line(n,color(n),all?2.3:3.2,all?(i>=6?'6 3':''):(n===other&&other!==focus?'7 4':''))).join('')}<line x1="${x(index)}" x2="${x(index)}" y1="${T}" y2="${H-B}" stroke="#555e49" stroke-dasharray="3 4"/>${names.map((owner,j)=>weeks.map((w,i)=>{const r=w.rows.find(r=>r.owner===owner),v=raceValue(r,metric);return v==null?'':`<circle cx="${x(i)}" cy="${y(v)}" r="${i===index?5:2.5}" fill="${color(owner)}" stroke="white" stroke-width="1"><title>${esc(teamName(owner))} · ${esc(w.label)} · ${esc(raceLabel(metric))}: ${raceNumber(v,metric)}</title></circle>`;}).join('')).join('')}${weeks.map((w,i)=>i===0||i===weeks.length-1||i%4===0?`<text x="${x(i)}" y="${H-9}" text-anchor="middle">W${w.period}</text>`:'').join('')}</svg></div><div class="legend race-legend">${names.map((n,i)=>`<span><i style="background:${color(n)}"></i>${esc(teamName(n))}${all&&i>=6?' · dashed':''}</span>`).join('')}</div>`;
}
function weeklyStory(season,focus,other){
 const i=weekIndex(season),week=season.weeks[i],previous=season.weeks[i-1],own=week.rows.find(r=>r.owner===focus),leader=week.rows[0];
 const delta=previous?previous.rows.find(r=>r.owner===focus).rank-own.rank:null;
 const climber=previous?week.rows.map(r=>({...r,gain:previous.rows.find(p=>p.owner===r.owner).rank-r.rank})).sort((a,b)=>b.gain-a.gain)[0]:null;
 return `<div class="story-metrics"><div><small>${esc(teamName(focus))}</small><strong>#${own.rank}<span>${own.pts} pts</span></strong><p>${delta==null?'Opening week':delta===0?'Held position':`${Math.abs(delta)} place${Math.abs(delta)===1?'':'s'} ${delta>0?'up':'down'} since last week`}</p></div><div><small>${week.rows.filter(r=>r.rank===1).length>1?'Joint leaders':'League leader'}</small><strong>${leader.pts}<span>pts</span></strong><p>${week.rows.filter(r=>r.rank===1).map(r=>esc(teamName(r.owner))).join(' · ')}</p></div><div><small>Biggest climb this week</small><strong>${climber?.gain>0?'↑ '+climber.gain:'—'}<span>${climber?.gain>0?(climber.gain===1?'place':'places'):''}</span></strong><p>${climber?.gain>0?esc(teamName(climber.owner))+(week.rows.filter(r=>previous.rows.find(p=>p.owner===r.owner).rank-r.rank===climber.gain).length>1?' (tied)':''):previous?'No upward rank changes':'The starting line'}</p></div></div>`;
}
function updateRace(){const season=D.weekly_standings.seasons[year],focus=$('#race-owner').value,other=$('#race-compare').value,metric=$('#race-metric').value;$('#race-chart').innerHTML=weeklyPlot(season,focus,other,metric);$('#race-story').innerHTML=raceStory(season,focus,other,metric);$('#race-week-label').textContent=season.weeks[weekIndex(season)].label;$('#race-data').innerHTML=raceData(season,metric);syncRaceUnits();}

function raceData(season,metric){return `<div class="table-wrap"><table><thead><tr><th>Period · ${esc(raceLabel(metric))}</th>${owners.map(o=>`<th>${esc(o.real_name)}</th>`).join('')}</tr></thead><tbody>${season.weeks.map(w=>`<tr><td>${esc(w.label)}</td>${owners.map(o=>`<td>${raceNumber(raceValue(w.rows.find(r=>r.owner===o.real_name),metric),metric)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function raceStory(season,focus,other,metric){if(['rank','pts'].includes(metric)&&param('raceScope')!=='all')return weeklyStory(season,focus,other);const week=season.weeks[weekIndex(season)],names=param('raceScope')==='all'?owners.map(o=>o.real_name):[...new Set([focus,other])];return `<div class="week-category-values">${names.map(owner=>{const row=week.rows.find(r=>r.owner===owner);return `<div><span>${esc(teamName(owner))}</span><strong>${raceNumber(raceValue(row,metric),metric)}</strong><small>${esc(raceLabel(metric))}</small></div>`;}).join('')}</div>`;}
function routePanel(){
 const owner=ownerMap[param('routeOwner')]?param('routeOwner'):ownerMap[param('filterOwner')]?param('filterOwner'):selectedOwner;
 const routes=DOTPInsights.tradeRoutes(D.trades.trade_events.filter(t=>t.year===year),owner),max=Math.max(1,...routes.flatMap(r=>[r.incoming,r.outgoing]));
 return panel('Trade routes',`${year} · player movement between trading partners`, `<div class="panel-body"><label class="select-label">Trace a team<select id="route-owner">${ownerOptions(owner)}</select></label><div class="route-key"><span><i class="route-in"></i>Players received</span><span><i class="route-out"></i>Players sent</span></div><div class="routes">${routes.map(r=>`<button type="button" class="route-row" data-route="${esc(r.owner)}" data-route-from="${esc(owner)}" aria-label="Show ${esc(owner)} trades with ${esc(r.owner)}"><span class="route-name">${badge(r.owner)}<span><strong>${esc(teamName(r.owner))}</strong><small>${r.events.length} shared trade${r.events.length===1?'':'s'}</small></span></span><span class="route-bars"><span><i class="route-in" style="width:${r.incoming/max*100}%"></i><b>${r.incoming}</b></span><span><i class="route-out" style="width:${r.outgoing/max*100}%"></i><b>${r.outgoing}</b></span></span>${icon('arrow')}</button>`).join('')||empty('No trade routes this season')}</div><p class="status-line">Click a partner to open those deals. Bars count player transfers; pick-only and budget-only deals can have zero players.</p></div>`);
}
function tradeSummary(){const ts=filteredTrades(),players=ts.reduce((n,t)=>n+Object.values(t.assets_by_party).reduce((m,a)=>m+a.received.length,0),0),picks=ts.reduce((n,t)=>n+t.pick_assets.length,0);return `<div class="story-metrics compact"><div><small>Matching deals</small><strong>${ts.length}</strong></div><div><small>Player transfers</small><strong>${players}</strong></div><div><small>Pick transfers</small><strong>${picks}</strong></div></div>`;}
function tradeOutcomes(t){
 const rows=t.parties.flatMap(owner=>t.assets_by_party[owner].received.map(name=>{const matches=Object.entries(playerMap).filter(([,p])=>p.player_name===name),id=matches.length===1?matches[0][0]:null;return {owner,name,id,now:id?rosterMap[id]:null};}));
 return rows.length?`<div class="mini-title"><h3>Where are they now?</h3><span class="pill">${currentYear} roster snapshot</span></div><div class="table-wrap"><table><thead><tr><th>Player</th><th>Acquired by</th><th>Now</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.id?assetPlayer(r.name):esc(r.name)}</td><td>${esc(teamName(r.owner,t.year))}</td><td>${!r.id?'Identity unresolved':!r.now?'<span class="muted">Not rostered</span>':r.now.owner_real_name===r.owner?'<span class="pill ACTIVE">With recipient</span>':`<a class="text-link" href="${teamUrl(r.now.owner_real_name)}">${esc(teamName(r.now.owner_real_name,currentYear))}</a>`}</td></tr>`).join('')}</tbody></table></div><p class="status-line">Current ownership can include a later reacquisition. This traces the assets; it does not score trade value or credit later production.</p>`:'';
}
function draftStories(){
 const season=D.draft_results.seasons.find(s=>s.year===year),picks=season?.picks||[],names=owners.map(o=>o.real_name),cohort=DOTPInsights.draftCohort(picks,rosterMap,names),owner=ownerMap[param('draftStoryOwner')]?param('draftStoryOwner'):selectedOwner;
 const selected=picks.filter(p=>p.pick_status==='selected'),survivors=selected.filter(p=>rosterMap[p.player_id]);
 const late=survivors.filter(p=>p.round>Math.ceil((season?.num_rounds||0)/2)).sort((a,b)=>b.overall_pick-a.overall_pick).slice(0,8);
 const classes=D.draft_results.seasons.map(s=>({year:s.year,...DOTPInsights.draftCohort(s.picks,rosterMap,names).find(r=>r.owner===owner)}));
 const row=cohort.find(r=>r.owner===owner);
 return `<div class="grid-two section-space">${panel('Draft staying power',`${year} class · retention grades, not production grades`,`<div class="panel-body"><div class="draft-headline"><strong>${survivors.length}<span> / ${selected.length}</span></strong><p>selected players remain on a league roster<br><small>${picks.length-selected.length} unfilled slots excluded · ${currentYear} snapshot</small></p></div><div class="survival-track" role="img" aria-label="${survivors.length} of ${selected.length} picks are currently rostered"><span style="width:${selected.length?survivors.length/selected.length*100:0}%"></span></div></div><div class="table-wrap"><table class="draft-cohort"><thead><tr><th>Drafting team</th><th>Rostered / selected</th><th>With drafter</th><th>Grade</th></tr></thead><tbody>${cohort.map(r=>`<tr class="${r.owner===owner?'selected':''}"><td><button class="draft-expand-team" data-draft-expand="${esc(r.owner)}" aria-expanded="false">${badge(r.owner)}<span>${esc(teamName(r.owner,year))}</span>${icon('chevron')}</button></td><td><strong>${r.rostered}/${r.selected}</strong> <small class="muted">${r.rate==null?'—':Math.round(r.rate*100)+'%'}</small></td><td>${r.retained}</td><td><span class="grade grade-${r.grade}" title="Class rank ${r.rank??'unavailable'} by roster survival rate">${r.grade}</span>${r.rank?` <small class="muted">#${r.rank}</small>`:''}</td></tr><tr class="draft-expanded-row" hidden><td colspan="4">${draftPickList(r.owner,year)}</td></tr>`).join('')}</tbody></table></div><details class="chart-detail panel-body"><summary>How these grades work</summary><p>Roster survival = selected players currently on any league roster ÷ selections. Rank within this draft class: 1–3 = A, 4–6 = B, 7–9 = C, 10–12 = D. Ties share a rank and grade. No selections = no grade. “With drafter” can include reacquisitions. Grades measure roster survival, not MLB production, profit, or prospect value. New classes have had less time to develop; 2019 was the full inaugural draft.</p></details>`)}<div class="stack">${panel('Late-round keepers',`Still rostered from the second half of the ${year} draft`,late.length?`<div class="keeper-list">${late.map(p=>`<div class="keeper-row"><span class="pick-token"><small>PICK</small>${p.overall_pick}</span><div>${playerLink(p.player_id,p.player_name,false)}<p>Round ${p.round} · drafted by ${esc(p.owner_name.split(' ').slice(-1)[0])}</p><small>Now: ${esc(teamName(rosterMap[p.player_id].owner_real_name,currentYear))}</small></div><span class="pill">${esc(rosterMap[p.player_id].roster_status)}</span></div>`).join('')}</div><div class="panel-foot">Deepest selections first · a starting point for finding draft steals, not a performance ranking.</div>`:empty('No late-round survivors','No selections from the second half of this draft are on the current roster snapshot.'))}${panel('Your draft classes','Roster survival and relative class grades, year by year',`<div class="panel-body"><label class="select-label">Drafting team<select id="draft-story-owner">${ownerOptions(owner)}</select></label><div class="draft-years">${classes.map(c=>`<details class="draft-class"><summary class="draft-year"><b>${c.year}</b><span class="bar-track"><span class="bar-fill" style="width:${(c.rate||0)*100}%"></span></span><strong>${c.rate==null?'—':Math.round(c.rate*100)+'%'}</strong><span class="grade grade-${c.grade}">${c.grade}</span>${icon('chevron')}</summary>${draftPickList(owner,c.year)}</details>`).join('')}</div><p class="status-line">Each grade compares owners in that year’s class. Rates use today’s roster snapshot and naturally decline as drafts age.</p></div>`)}</div></div>`;
}
let journeyTimer=null;
function stopJourney(){if(journeyTimer){clearInterval(journeyTimer);journeyTimer=null;}const button=$('#journey-play');if(button)button.textContent='Play journey';}
function journeyReplay(id){
 const stints=(stintsByPlayer[id]||[]).slice().sort((a,b)=>a.start_date.localeCompare(b.start_date));if(!stints.length)return '';
 const n=Math.max(0,Math.min(stints.length-1,Number(param('journeyStep',0))||0));
 return panel('Replay the journey',`${stints.length} recorded acquisitions · step through the owners`, `<div class="panel-body"><div class="journey-strip" aria-label="Recorded acquisitions">${stints.map((s,i)=>`<button type="button" data-journey-step="${i}" aria-label="Acquisition ${i+1}: ${esc(s.owner_real_name)}, ${date(s.start_date)}" aria-pressed="${i===n}" style="--journey-color:${colors[ownerMap[s.owner_real_name]?.color_index||0][1]}"><span>${i+1}</span><small>${s.start_date.slice(0,4)}</small></button>`).join('')}</div><div class="scrub-control"><button type="button" class="btn" id="journey-play">Play journey</button><input type="range" id="journey-step" aria-label="Ownership acquisition" min="0" max="${stints.length-1}" value="${n}" data-player-id="${esc(id)}"><output id="journey-step-label">${n+1} / ${stints.length}</output></div><div id="journey-scene" aria-live="polite">${journeyScene(stints,n)}</div><p class="status-line">Each stop is a recorded acquisition, not an equal period of time. A new stop may follow a free-agent gap; it does not imply a direct trade.</p></div>`,'','journey-panel section-space');
}
function journeyScene(stints,n){const s=stints[n],previous=stints[n-1];const gap=previous?.end_date&&previous.end_date<s.start_date?Math.round((new Date(s.start_date)-new Date(previous.end_date))/86400000):0;return `<div class="journey-scene">${badge(s.owner_real_name,true)}<div><span class="eyebrow">${date(s.start_date)} · ${esc(s.acquisition_type.toLowerCase())}</span><h3>${esc(s.team_name)}</h3><p>${esc(s.owner_real_name)} · ${s.is_current?'Current recorded stint':s.end_date_unknown?'Exit date unavailable':'Held through '+date(s.end_date)}</p>${gap>1?`<small class="muted">${gap} days between recorded ownership stints</small>`:''}</div><div class="journey-duration"><strong>${s.tenure_days??(s.is_current?rosterMap[s.player_id]?.days_on_team:'—')??'—'}</strong><small>days in this stint</small></div></div>`;}
function updateJourney(n){const slider=$('#journey-step');if(!slider)return;const id=slider.dataset.playerId,stints=(stintsByPlayer[id]||[]).slice().sort((a,b)=>a.start_date.localeCompare(b.start_date));n=Math.max(0,Math.min(stints.length-1,n));slider.value=n;setParams({journeyStep:n});$('#journey-step-label').textContent=`${n+1} / ${stints.length}`;$('#journey-scene').innerHTML=journeyScene(stints,n);document.querySelectorAll('[data-journey-step]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.journeyStep)===n));}
function bindStoryControls(){
 for(const [id,key] of [['race-owner','raceOwner'],['race-compare','raceCompare'],['race-metric','raceMetric']])$('#'+id)?.addEventListener('change',e=>{setParams({[key]:e.target.value});updateRace();});
 $('#race-week')?.addEventListener('input',e=>{setParams({week:e.target.value});updateRace();});
 $('#route-owner')?.addEventListener('change',e=>{setParams({routeOwner:e.target.value});render();});
 $('#draft-story-owner')?.addEventListener('change',e=>{setParams({draftStoryOwner:e.target.value});render();});
 $('#journey-step')?.addEventListener('input',e=>{stopJourney();updateJourney(Number(e.target.value));});
 $('#journey-play')?.addEventListener('click',()=>{if(journeyTimer){stopJourney();return;}const slider=$('#journey-step');if(Number(slider.value)>=Number(slider.max))updateJourney(0);$('#journey-play').textContent='Pause journey';journeyTimer=setInterval(()=>{const next=Number(slider.value)+1;if(next>Number(slider.max)){stopJourney();return;}updateJourney(next);if(next===Number(slider.max))stopJourney();},1600);});
}
window.addEventListener('pagehide',stopJourney);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopJourney();});
document.addEventListener('click',e=>{
 const route=e.target.closest('[data-route]');if(route){page=1;setParams({filterOwner:route.dataset.routeFrom,partner:route.dataset.route,q:null,type:null,month:null,page:null});render();$('#trade-results').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
 const month=e.target.closest('[data-trade-month]');if(month){page=1;setParams({month:month.dataset.tradeMonth===param('month')?null:month.dataset.tradeMonth,page:null});render();}
 const step=e.target.closest('[data-journey-step]');if(step){stopJourney();updateJourney(Number(step.dataset.journeyStep));}
});

const raceMetrics={rank:'League rank',pts:'Roto points',r:'Runs',hr:'Home runs',rbi:'RBI',sb:'Stolen bases',obp:'OBP',k:'Strikeouts',era:'ERA',whip:'WHIP',svh3:'Saves + half holds',wqs:'Wins + quality starts'};
const raceColors=['#146345','#bd7900','#4169a1','#ad4662','#6653a0','#8a681f','#117f89','#a14d29','#73902a','#ba3b3b','#536371','#9b5086'];
const raceIsRoto=metric=>!['rank','pts'].includes(metric)&&param('raceUnits','roto')!=='raw';
const raceLabel=metric=>raceMetrics[metric]+(raceIsRoto(metric)?' · roto points':'');
const raceValue=(row,metric)=>['rank','pts'].includes(metric)?row[metric]:raceIsRoto(metric)?row.category_points?.[metric]:row.stats?.[metric];
const raceNumber=(value,metric)=>value==null?'—':raceIsRoto(metric)?fmt(value):['obp','whip'].includes(metric)?Number(value).toFixed(3):metric==='era'?Number(value).toFixed(2):fmt(value);
function draftPickList(owner,season){const picks=D.draft_results.seasons.find(s=>s.year===Number(season))?.picks.filter(p=>p.owner_name===owner)||[];return `<div class="expanded-picks"><strong>${season} selections · ${esc(teamName(owner,season))}</strong>${picks.length?`<div class="pick-cards">${picks.map(p=>`<div><span class="pick-label">#${p.overall_pick} · R${p.round}</span>${p.pick_status==='selected'?`<a href="${playerUrl(p.player_id)}">${esc(p.player_name)}</a><small>${rosterMap[p.player_id]?'Now: '+esc(teamName(rosterMap[p.player_id].owner_real_name,currentYear)):'Not currently rostered'}</small>`:'<span>Unfilled slot</span>'}</div>`).join('')}</div>`:empty('No selections in this class')}</div>`;}
function draftCompare(){const a=ownerMap[param('draftStoryOwner')]?param('draftStoryOwner'):selectedOwner,b=ownerMap[param('draftCompare')]?param('draftCompare'):owners.find(o=>o.real_name!==a).real_name,season=D.draft_results.seasons.find(s=>s.year===year);const cohort=DOTPInsights.draftCohort(season?.picks||[],rosterMap,owners.map(o=>o.real_name));return panel('Compare two draft classes',`${year} · actual selections and current roster survival`, `<div class="panel-body"><div class="grid-two">${[a,b].map(owner=>{const r=cohort.find(r=>r.owner===owner);return `<section class="draft-compare-card">${teamCell(owner,year)}<div class="comparison-score"><span class="grade grade-${r.grade}">${r.grade}</span><strong>${r.rostered}/${r.selected}</strong><span>still rostered · ${r.retained} with drafter</span></div>${draftPickList(owner,year)}</section>`;}).join('')}</div><div class="story-controls controls-bottom"><label>First team<select id="draft-compare-a">${ownerOptions(a)}</select></label><label>Second team<select id="draft-compare-b">${ownerOptions(b)}</select></label></div></div>`,'','section-space');}
function draftRankings(){const rows=DOTPInsights.draftHistory(D.draft_results.seasons,rosterMap,owners.map(o=>o.real_name));return panel('Draft rankings through the years','Average class rank by roster survival · lower is better',`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Team</th><th>Average class rank</th><th>Classes</th><th>A grades</th>${D.teams.meta.seasons.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td><strong>#${r.rank}</strong></td><td>${teamCell(r.owner)}</td><td><strong>${r.average.toFixed(2)}</strong></td><td>${r.classes.length}</td><td>${r.classes.filter(c=>c.grade==='A').length}</td>${D.teams.meta.seasons.map(y=>{const c=r.classes.find(c=>c.year===y);return `<td>${c?`<a class="grade grade-${c.grade}" href="${url('drafts.html',{season:y,filterOwner:r.owner,draftStoryOwner:r.owner})}#draft-results" aria-label="${esc(r.owner)}, ${y} picks, grade ${c.grade}">${c.grade}</a>`:'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-foot">Each draft class counts equally; ties share rank. Classes with no selections are excluded. This ranks roster survival, not player production or trade value.</div>`,'','section-space');}
function openInlinePlayer(button){const row=button.closest('tr'),id=button.dataset.expandPlayer;let extra=row.nextElementSibling;if(!extra?.classList.contains('expanded-player-row')){extra=document.createElement('tr');extra.className='expanded-player-row';extra.id='player-expand-'+id;const cell=document.createElement('td');cell.colSpan=row.children.length;cell.innerHTML=playerProfile(id);extra.append(cell);row.after(extra);extra.hidden=true;}extra.hidden=!extra.hidden;button.setAttribute('aria-expanded',String(!extra.hidden));}
function bindFinalControls(){
 for(const [id,key] of [['draft-compare-a','draftStoryOwner'],['draft-compare-b','draftCompare']])$('#'+id)?.addEventListener('change',e=>{setParams({[key]:e.target.value});render();});
 $('#race-scope')?.addEventListener('change',e=>{setParams({raceScope:e.target.value});updateRace();});
}
document.addEventListener('click',e=>{
 const draft=e.target.closest('[data-draft-expand]');if(draft){const row=draft.closest('tr'),extra=row.nextElementSibling;extra.hidden=!extra.hidden;draft.setAttribute('aria-expanded',String(!extra.hidden));}
 const player=e.target.closest('[data-expand-player]');if(player)openInlinePlayer(player);
 const clear=e.target.closest('[data-clear-trades]');if(clear){page=1;setParams({filterOwner:null,partner:null,q:null,type:null,month:null,routeOwner:null,page:null});render();}
});

function historyRace(){return panel('The league through the years','All 12 franchises · season finishes from 2019 to 2026',`<div class="panel-body"><div id="history-race-chart">${historyRacePlot()}</div><div class="story-controls controls-bottom"><label for="history-metric">Chart<select id="history-metric"><option value="rank">Finishing rank</option><option value="pts" ${param('historyMetric')==='pts'?'selected':''}>Roto points</option></select></label><label for="history-focus">Highlight a team<select id="history-focus">${ownerOptions(param('historyFocus'),true)}</select></label></div><details class="chart-detail"><summary>View season results</summary><div class="table-wrap"><table><thead><tr><th>Owner</th>${D.teams.meta.seasons.map(y=>`<th>${y}</th>`).join('')}</tr></thead><tbody>${owners.map(o=>`<tr><td>${teamCell(o.real_name,currentYear)}</td>${D.teams.meta.seasons.map(y=>{const r=ownerStanding(o.real_name,y);return `<td>${r?'#'+r.rank+' · '+r.pts+' pts':'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details></div>`,'','section-space history-race-panel');}
function historyRacePlot(){
 const years=D.teams.meta.seasons,metric=param('historyMetric')==='pts'?'pts':'rank',focus=ownerMap[param('historyFocus')]?param('historyFocus'):'',W=760,H=310,L=40,R=24,T=22,B=38;
 const x=i=>L+i/Math.max(1,years.length-1)*(W-L-R),y=n=>T+(metric==='rank'?(n-1)/11:(120-n)/120)*(H-T-B),ticks=metric==='rank'?[1,3,6,9,12]:[0,30,60,90,120];
 const ordered=owners.slice().sort((a,b)=>(a.real_name===focus?1:0)-(b.real_name===focus?1:0));
 return `<div class="chart-caption">${metric==='rank'?'Final league rank · first place at the top':'Final rotisserie points · higher is better'}</div><div class="chart-scroll"><svg class="race-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="All teams, 2019 through 2026, ${metric==='rank'?'season finishing ranks':'season rotisserie points'}">${ticks.map(t=>`<line class="axis" x1="${L}" x2="${W-R}" y1="${y(t)}" y2="${y(t)}"/><text x="4" y="${y(t)+4}">${t}</text>`).join('')}${ordered.map(o=>{const i=owners.findIndex(p=>p.real_name===o.real_name),color=raceColors[i],muted=focus&&focus!==o.real_name,rows=years.map(yr=>ownerStanding(o.real_name,yr));let path='',active=false;rows.forEach((r,j)=>{if(!r){active=false;return;}path+=`${active?'L':'M'}${x(j)},${y(r[metric])} `;active=true;});return `<g opacity="${muted?.18:1}"><path d="${path}" fill="none" stroke="${color}" stroke-width="${o.real_name===focus?4:2.3}" ${i>=6?'stroke-dasharray="7 4"':''}/>${rows.map((r,j)=>r?`<circle cx="${x(j)}" cy="${y(r[metric])}" r="${o.real_name===focus?5:3.5}" fill="${color}" stroke="white" stroke-width="1.2"><title>${esc(o.real_name)} · ${r.season} · ${esc(r.team_name)} · rank ${r.rank} · ${r.pts} points</title></circle>`:'').join('')}</g>`;}).join('')}${years.map((yr,i)=>`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${yr}</text>`).join('')}</svg></div><div class="legend race-legend">${owners.map((o,i)=>`<button class="history-legend-button" data-history-focus="${esc(o.real_name)}" aria-pressed="${focus===o.real_name}" style="${focus&&focus!==o.real_name?'opacity:.55':''}"><i style="background:${raceColors[i]}"></i>${esc(o.current_team)}${i>=6?' · dashed':''}</button>`).join('')}</div><p class="status-line">Click a legend name to highlight its history; click it again to return to all teams. Franchises are matched by owner across team-name changes.</p>`;
}
function raceUnitsNote(metric){return raceIsRoto(metric)?'Category roto points · higher is better for every category · Fantrax tie adjustments included.':metric==='rank'?'League rank · first place at the top.':metric==='pts'?'Total rotisserie points · higher is better.':'Raw cumulative stats · lower ERA and WHIP are better · rates come directly from Fantrax, not weekly averages.';}
function syncRaceUnits(){const metric=$('#race-metric')?.value||'rank',category=!['rank','pts'].includes(metric);document.querySelectorAll('[data-race-units]').forEach(b=>{b.disabled=!category;b.setAttribute('aria-pressed',param('raceUnits','roto')===b.dataset.raceUnits);});const note=$('#race-units-note');if(note)note.textContent=raceUnitsNote(metric);}
function bindHistoryControls(){for(const [id,key] of [['history-metric','historyMetric'],['history-focus','historyFocus']])$('#'+id)?.addEventListener('change',e=>{setParams({[key]:e.target.value});$('#history-race-chart').innerHTML=historyRacePlot();});syncRaceUnits();}
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-race-units]');if(toggle&&!toggle.disabled){setParams({raceUnits:toggle.dataset.raceUnits});updateRace();}const legend=e.target.closest('[data-history-focus]');if(legend){const owner=param('historyFocus')===legend.dataset.historyFocus?'':legend.dataset.historyFocus;setParams({historyFocus:owner});$('#history-focus').value=owner;$('#history-race-chart').innerHTML=historyRacePlot();}});

function render(){stopJourney();const main=$('#main-content');const renderers={overview,teams,players,player:()=>playerProfile(param('id'),true),trades,standings,drafts,history:leagueHistory};main.innerHTML=(renderers[view]||overview)()+footer();bindControls();bindStoryControls();bindFinalControls();bindHistoryControls();}
function refreshResults(){if(view==='players'||(view==='teams'&&param('tab','roster')==='roster'))$('#player-results').innerHTML=playerTable(tableRows);else if(view==='trades'){$('#trade-results').innerHTML=tradeList(filteredTrades());$('#trade-summary').innerHTML=tradeSummary();}else if(view==='drafts')$('#draft-results').innerHTML=draftTable();else render();}
function bindControls(){const configs=[['player-filter','q'],['owner-filter','filterOwner'],['status-filter','status'],['position-filter','position'],['trade-filter','q'],['trade-owner','filterOwner'],['trade-partner','partner'],['trade-type','type'],['draft-filter','q'],['draft-owner','filterOwner']];configs.forEach(([id,key])=>{const el=$('#'+id);if(el)el.addEventListener(el.tagName==='INPUT'?'input':'change',e=>{page=1;setParams({[key]:e.target.value,page:null,...(id==='trade-owner'&&!e.target.value?{partner:null,routeOwner:null}: {})});if(id==='trade-owner'&&!e.target.value)render();else refreshResults();});});$('#team-switch')?.addEventListener('change',e=>{location.href=url('team.html',{owner:e.target.value,tab:param('tab','roster')});});$('#compare-owner')?.addEventListener('change',e=>{setParams({compare:e.target.value});render();});}
function showDialog(type,id,trigger,fromUrl=false){const dialog=$('#detail-dialog');dialogTrigger=trigger||document.activeElement;const title=type==='player'?'Player quick view':'Trade details';dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close-btn" aria-label="Close details" data-close>${icon('close')}</button></div><div class="modal-content">${type==='player'?playerProfile(id):tradeDetail(id)}</div>`;if(!dialog.open)dialog.showModal();if(!fromUrl)setParams({[type==='player'?'quickPlayer':'trade']:id},true);}
function restoreDialog(){const p=params();if(p.has('quickPlayer'))showDialog('player',p.get('quickPlayer'),null,true);else if(p.has('trade'))showDialog('trade',p.get('trade'),null,true);else if($('#detail-dialog').open)$('#detail-dialog').close();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-player],[data-trade],[data-close],[data-menu],[data-page-step],[data-sort],[data-reset],[data-select-owner]');if(el){if(el.hasAttribute('data-select-owner')){selectTeam(el.dataset.selectOwner);}else if(el.hasAttribute('data-player')){if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();showDialog('player',el.dataset.player,el);}else if(el.hasAttribute('data-trade')){if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();showDialog('trade',el.dataset.trade,el);}else if(el.hasAttribute('data-close'))closeDialog();else if(el.hasAttribute('data-menu')){document.body.classList.toggle('menu-open');$('.mobile-menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));}else if(el.hasAttribute('data-page-step')){page+=Number(el.dataset.pageStep);setParams({page});refreshResults();}else if(el.hasAttribute('data-sort')){sortDirection=sortKey===el.dataset.sort?-sortDirection:1;sortKey=el.dataset.sort;setParams({sort:sortKey,dir:sortDirection});refreshResults();}else if(el.hasAttribute('data-reset')){page=1;setParams({q:null,filterOwner:null,status:null,position:null,partner:null,type:null,month:null,page:null});render();}}if(!e.target.closest('.top-search'))closeSearch();if(!e.target.closest('.team-picker'))closeTeamPicker();});
function closeDialog(){setParams({quickPlayer:null,trade:null});$('#detail-dialog').close();dialogTrigger?.focus();}
$('#detail-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open){e.preventDefault();$('#global-search')?.focus();}if(e.key==='Escape'){closeSearch();const picker=$('#selected-team-options');if(picker&&!picker.hidden){closeTeamPicker(true);}else if(document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');$('.mobile-menu')?.setAttribute('aria-expanded','false');$('.mobile-menu')?.focus();}}if(e.key==='ArrowDown'&&e.target.closest('#global-results')){e.preventDefault();const links=[...document.querySelectorAll('#global-results a')],index=links.indexOf(e.target.closest('a'));links[(index+1)%links.length]?.focus();}if(e.key==='ArrowUp'&&e.target.closest('#global-results')){e.preventDefault();const links=[...document.querySelectorAll('#global-results a')],index=links.indexOf(e.target.closest('a'));if(index===0)$('#global-search').focus();else links[index-1]?.focus();}});
window.addEventListener('popstate',()=>{year=Number(param('season',currentYear));page=Number(param('page',1))||1;sortKey=param('sort','player_name');sortDirection=Number(param('dir',1))||1;$('#season-select').value=year;shellNavUpdate();render();restoreDialog();});
async function init(){try{const names=['teams','rosters','journeys','standings','trades','refresh_status','trade_production_2026',...(view==='drafts'?['draft_results','picks']:[]),...(view==='standings'?['weekly_standings']:[])];const data=await Promise.all(names.map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw Error(`Unable to load ${name}`);return r.json();}));names.forEach((n,i)=>D[n]=data[i]);for(const p of [...D.rosters.players,...Object.values(D.rosters.by_owner).flat()]){if(p.roster_status==='INJURED_RESERVE')p.roster_status='IR';}owners=D.teams.owners;ownerMap=Object.fromEntries(owners.map(o=>[o.real_name,o]));playerMap=D.journeys.player_index;rosterMap=Object.fromEntries(D.rosters.players.map(p=>[p.player_id,p]));D.journeys.stints.forEach(s=>(stintsByPlayer[s.player_id] ||= []).push(s));currentYear=D.rosters.meta.season;year=Number(param('season',currentYear));if(!D.teams.meta.seasons.includes(year))year=currentYear;let saved;try{saved=localStorage.getItem('dotp_selected_owner');}catch{}selectedOwner=ownerMap[saved]?saved:'Matthew Zujewski';page=Math.max(1,Number(param('page',1))||1);sortKey=param('sort','player_name');sortDirection=param('dir')==='-1'?-1:1;shell();render();restoreDialog();if(location.hash==='#draft-results')$('#draft-results')?.scrollIntoView({block:'start'});}catch(err){$('#app').innerHTML=`<div class="loading"><img src="assets/dotp-crest.png" alt="DOTP"><h1>The clubhouse couldn’t load.</h1><p>Please refresh to try again. Your saved league records have not changed.</p><p class="muted small">${esc(err.message)}</p><button class="btn" onclick="location.reload()">Try again</button></div>`;console.error(err);}}
init();
})();
